def k_machine_schedule(jobs: list[list[int]], k: int) -> int:
    if not jobs or k <= 0:
        return 0

    import heapq

    times = sorted({t for start, end, _pay in jobs for t in (start, end)})
    index = {t: i for i, t in enumerate(times)}
    node_count = len(times)
    graph: list[list[list[int]]] = [[] for _ in range(node_count)]

    def add_edge(u: int, v: int, cap: int, cost: int) -> None:
        graph[u].append([v, cap, cost, len(graph[v])])
        graph[v].append([u, 0, -cost, len(graph[u]) - 1])

    for node in range(node_count - 1):
        add_edge(node, node + 1, k, 0)
    for start, end, pay in jobs:
        add_edge(index[start], index[end], 1, -pay)

    source, sink = 0, node_count - 1
    inf = 10**18
    potential = [inf] * node_count
    potential[source] = 0
    for u in range(node_count):
        if potential[u] == inf:
            continue
        for edge in graph[u]:
            v, cap, cost, _rev = edge
            if cap > 0 and potential[u] + cost < potential[v]:
                potential[v] = potential[u] + cost

    total_cost = 0
    sent = 0
    while sent < k:
        dist = [inf] * node_count
        dist[source] = 0
        parent_node = [-1] * node_count
        parent_edge = [-1] * node_count
        heap = [(0, source)]
        while heap:
            d, u = heapq.heappop(heap)
            if d != dist[u]:
                continue
            for ei, edge in enumerate(graph[u]):
                v, cap, cost, _rev = edge
                if cap <= 0:
                    continue
                nd = d + cost + potential[u] - potential[v]
                if nd < dist[v]:
                    dist[v] = nd
                    parent_node[v] = u
                    parent_edge[v] = ei
                    heapq.heappush(heap, (nd, v))
        if dist[sink] == inf:
            break
        for i in range(node_count):
            if dist[i] < inf:
                potential[i] += dist[i]

        add = k - sent
        v = sink
        while v != source:
            u = parent_node[v]
            cap = graph[u][parent_edge[v]][1]
            if cap < add:
                add = cap
            v = u
        if add <= 0:
            break

        v = sink
        while v != source:
            u = parent_node[v]
            edge = graph[u][parent_edge[v]]
            edge[1] -= add
            graph[v][edge[3]][1] += add
            total_cost += add * edge[2]
            v = u
        sent += add

    return -total_cost
